using System;

public class Solution
{
    public string[] FindRelativeRanks(int[] score)
    {
        int n = score.Length;
        string[] answer = new string[n];

        // Step 1: Create a list of tuples (score, index)
        int[][] scoreIndexPairs = new int[n][];
        for (int i = 0; i < n; i++)
        {
            scoreIndexPairs[i] = new int[2];
            scoreIndexPairs[i][0] = score[i];
            scoreIndexPairs[i][1] = i;
        }

        // Step 2: Sort the list of tuples in descending order based on scores
        for (int i = 0; i < n - 1; i++)
        {
            for (int j = 0; j < n - i - 1; j++)
            {
                if (scoreIndexPairs[j][0] < scoreIndexPairs[j + 1][0])
                {
                    // Swap
                    int[] temp = scoreIndexPairs[j];
                    scoreIndexPairs[j] = scoreIndexPairs[j + 1];
                    scoreIndexPairs[j + 1] = temp;
                }
            }
        }

        // Step 3: Assign ranks based on the sorted order
        for (int i = 0; i < n; i++)
        {
            if (i == 0)
            {
                answer[scoreIndexPairs[i][1]] = "Gold Medal";
            }
            else if (i == 1)
            {
                answer[scoreIndexPairs[i][1]] = "Silver Medal";
            }
            else if (i == 2)
            {
                answer[scoreIndexPairs[i][1]] = "Bronze Medal";
            }
            else
            {
                answer[scoreIndexPairs[i][1]] = (i + 1).ToString();
            }
        }

        return answer;
    }
}

