using System;

public class Solution
{
    public string TruncateSentence(string s, int k)
    {
        // Initialize a StringBuilder to build the result
        var result = new System.Text.StringBuilder();

        // Initialize a counter for the number of words processed
        int wordCount = 0;

        // Iterate through each character in the string
        for (int i = 0; i < s.Length; i++)
        {
            // Check if the current character is a space
            if (s[i] == ' ')
            {
                // Increment the word counter
                wordCount++;

                // If we have processed k words, break out of the loop
                if (wordCount == k)
                {
                    break;
                }
            }

            // Append the current character to the result
            result.Append(s[i]);
        }

        // Convert the StringBuilder to a string and return it
        return result.ToString();
    }

    public static void Main()
    {
        Solution solution = new Solution();

        // Test cases
        Console.WriteLine(solution.TruncateSentence("Hello how are you Contestant", 4)); // Output: "Hello how are you"
        Console.WriteLine(solution.TruncateSentence("What is the solution to this problem", 4)); // Output: "What is the solution"
        Console.WriteLine(solution.TruncateSentence("chopper is not a tanuki", 5)); // Output: "chopper is not a tanuki"
    }
}

