using System;

public class Solution
{
    public string StringShift(string s, int[][] shift)
    {
        int n = s.Length;
        int netShift = 0;

        // Calculate net shift
        foreach (var sh in shift)
        {
            int direction = sh[0];
            int amount = sh[1];

            if (direction == 0)
            {
                // Left shift
                netShift += n - amount;
            }
            else
            {
                // Right shift
                netShift += amount;
            }
        }

        // Normalize net shift to be within the bounds of the string length
        netShift %= n;

        // If netShift is negative, convert it to a positive equivalent
        if (netShift < 0)
        {
            netShift += n;
        }

        // Apply the net shift
        string result = s.Substring(n - netShift) + s.Substring(0, n - netShift);

        return result;
    }

    public static void Main()
    {
        Solution solution = new Solution();

        // Example 1
        string s1 = "abc";
        int[][] shift1 = new int[][]
        {
            new int[] { 0, 1 },
            new int[] { 1, 2 }
        };
        Console.WriteLine(solution.StringShift(s1, shift1)); // Output: "cab"

        // Example 2
        string s2 = "abcdefg";
        int[][] shift2 = new int[][]
        {
            new int[] { 1, 1 },
            new int[] { 1, 1 },
            new int[] { 0, 2 },
            new int[] { 1, 3 }
        };
        Console.WriteLine(solution.StringShift(s2, shift2)); // Output: "efgabcd"
    }
}

