using System;

public class Solution {
    public string MergeAlternately(string word1, string word2) {
        // Initialize an array to hold the merged characters
        char[] merged = new char[word1.Length + word2.Length];

        // Initialize indices for word1, word2, and the merged array
        int i = 0, j = 0, k = 0;

        // Loop until we reach the end of either word1 or word2
        while (i < word1.Length && j < word2.Length) {
            // Add character from word1 to the merged array
            merged[k++] = word1[i++];
            // Add character from word2 to the merged array
            merged[k++] = word2[j++];
        }

        // If there are remaining characters in word1, add them to the merged array
        while (i < word1.Length) {
            merged[k++] = word1[i++];
        }

        // If there are remaining characters in word2, add them to the merged array
        while (j < word2.Length) {
            merged[k++] = word2[j++];
        }

        // Convert the merged character array to a string and return it
        return new string(merged);
    }

    public static void Main(string[] args) {
        Solution solution = new Solution();

        // Test cases
        Console.WriteLine(solution.MergeAlternately("abc", "pqr")); // Output: "apbqcr"
        Console.WriteLine(solution.MergeAlternately("ab", "pqrs")); // Output: "apbqrs"
        Console.WriteLine(solution.MergeAlternately("abcd", "pq")); // Output: "apbqcd"
    }
}

