using System;

public class Solution {
    public int[] SmallerNumbersThanCurrent(int[] nums) {
        // Step 1: Create a copy of the original array and sort it
        int[] sortedNums = new int[nums.Length];
        for (int i = 0; i < nums.Length; i++) {
            sortedNums[i] = nums[i];
        }

        // Sort the copied array
        for (int i = 0; i < sortedNums.Length - 1; i++) {
            for (int j = i + 1; j < sortedNums.Length; j++) {
                if (sortedNums[i] > sortedNums[j]) {
                    // Swap elements
                    int temp = sortedNums[i];
                    sortedNums[i] = sortedNums[j];
                    sortedNums[j] = temp;
                }
            }
        }

        // Step 2: For each element in the original array, find its index in the sorted array
        int[] result = new int[nums.Length];
        for (int i = 0; i < nums.Length; i++) {
            int count = 0;
            for (int j = 0; j < sortedNums.Length; j++) {
                if (sortedNums[j] < nums[i]) {
                    count++;
                } else {
                    break; // Since the array is sorted, no need to check further
                }
            }
            result[i] = count;
        }

        return result;
    }

    public static void Main(string[] args) {
        Solution solution = new Solution();

        // Example 1
        int[] nums1 = {8, 1, 2, 2, 3};
        int[] result1 = solution.SmallerNumbersThanCurrent(nums1);
        Console.WriteLine(string.Join(", ", result1)); // Output: 4, 0, 1, 1, 3

        // Example 2
        int[] nums2 = {6, 5, 4, 8};
        int[] result2 = solution.SmallerNumbersThanCurrent(nums2);
        Console.WriteLine(string.Join(", ", result2)); // Output: 2, 1, 0, 3

        // Example 3
        int[] nums3 = {7, 7, 7, 7};
        int[] result3 = solution.SmallerNumbersThanCurrent(nums3);
        Console.WriteLine(string.Join(", ", result3)); // Output: 0, 0, 0, 0
    }
}

