using System;
using System.Collections.Generic;

public class TreeNode
{
    public int val;
    public TreeNode left;
    public TreeNode right;
    public TreeNode(int x) { val = x; }
}

public class Solution
{
    public List<int> GetLonelyNodes(TreeNode root)
    {
        List<int> lonelyNodes = new List<int>();
        Dfs(root, lonelyNodes);
        return lonelyNodes;
    }

    private void Dfs(TreeNode node, List<int> lonelyNodes)
    {
        if (node == null)
        {
            return;
        }

        // Check if the current node is lonely
        if (node.left != null && node.right == null)
        {
            lonelyNodes.Add(node.left.val);
        }
        else if (node.left == null && node.right != null)
        {
            lonelyNodes.Add(node.right.val);
        }

        // Traverse the left and right subtrees
        Dfs(node.left, lonelyNodes);
        Dfs(node.right, lonelyNodes);
    }

    public static void Main(string[] args)
    {
        // Example usage:
        TreeNode root = new TreeNode(1);
        root.left = new TreeNode(2);
        root.right = new TreeNode(3);
        root.left.right = new TreeNode(4);

        Solution solution = new Solution();
        List<int> result = solution.GetLonelyNodes(root);

        Console.WriteLine("Lonely nodes: " + string.Join(", ", result));
    }
}

