public class Solution {
    public int MaxAscendingSum(int[] nums) {
        // Initialize variables
        int maxSum = 0; // To store the maximum sum of ascending subarrays
        int currentSum = 0; // To store the current ascending subarray sum

        // Iterate through the array
        for (int i = 0; i < nums.Length; i++) {
            // If it's the first element or the current element is greater than the previous one
            if (i == 0 || nums[i] > nums[i - 1]) {
                // Add the current element to the current sum
                currentSum += nums[i];
            } else {
                // Compare the current sum with the max sum and update max sum if necessary
                if (currentSum > maxSum) {
                    maxSum = currentSum;
                }
                // Reset the current sum to the current element
                currentSum = nums[i];
            }
        }

        // Final check to update max sum if the last subarray is the maximum
        if (currentSum > maxSum) {
            maxSum = currentSum;
        }

        return maxSum;
    }
}

