public class Solution {
    public int MaxSubarraySumAfterOperation(int[] nums) {
        if (nums == null || nums.Length == 0) {
            return 0;
        }

        int maxSumWithoutOp = nums[0];
        int maxSumWithOp = nums[0] * nums[0];
        int currentSumWithoutOp = nums[0];
        int currentSumWithOp = nums[0] * nums[0];

        for (int i = 1; i < nums.Length; i++) {
            int num = nums[i];

            // Update current subarray sums
            currentSumWithoutOp = Math.Max(num, currentSumWithoutOp + num);
            currentSumWithOp = Math.Max(
                num * num + currentSumWithoutOp,
                Math.Max(currentSumWithOp + num, num * num)
            );

            // Update maximum subarray sums
            maxSumWithoutOp = Math.Max(maxSumWithoutOp, currentSumWithoutOp);
            maxSumWithOp = Math.Max(maxSumWithOp, currentSumWithOp);
        }

        // Return the maximum of both sums
        return Math.Max(maxSumWithoutOp, maxSumWithOp);
    }
}

