using System;
using System.Collections.Generic;

public class Solution {
    public int MaxNonOverlappingSubarrays(int[] nums, int target) {
        int prefixSum = 0;
        int count = 0;
        HashSet<int> seenSums = new HashSet<int>();

        for (int i = 0; i < nums.Length; i++) {
            prefixSum += nums[i];

            // Check if the current prefix sum is equal to the target
            if (prefixSum == target) {
                count++;
                seenSums.Clear();
            } else {
                // Check if there is a previous prefix sum such that
                // prefixSum - previousPrefixSum = target
                if (seenSums.Contains(prefixSum - target)) {
                    count++;
                    seenSums.Clear();
                }
            }

            // Add the current prefix sum to the set
            seenSums.Add(prefixSum);
        }

        return count;
    }
}

