public class Solution {
    public int MaxBoxesInWarehouse(int[] boxes, int[] warehouse) {
        // Step 1: Sort the boxes
        Array.Sort(boxes);

        int n = warehouse.Length;
        int[] left_min = new int[n];
        int[] right_min = new int[n];

        // Step 2: Fill the left_min array
        left_min[0] = warehouse[0];
        for (int i = 1; i < n; i++) {
            left_min[i] = Math.Min(left_min[i - 1], warehouse[i]);
        }

        // Step 3: Fill the right_min array
        right_min[n - 1] = warehouse[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            right_min[i] = Math.Min(right_min[i + 1], warehouse[i]);
        }

        // Step 4: Determine effective heights
        int[] effective_heights = new int[n];
        for (int i = 0; i < n; i++) {
            effective_heights[i] = Math.Max(left_min[i], right_min[i]);
        }

        // Step 5: Place the boxes
        int boxIndex = 0;
        int left = 0;
        int right = n - 1;
        int placedBoxes = 0;

        while (boxIndex < boxes.Length && left <= right) {
            int currentBoxHeight = boxes[boxIndex];

            // Choose the side with the higher effective height
            if (effective_heights[left] >= effective_heights[right]) {
                if (currentBoxHeight <= effective_heights[left]) {
                    placedBoxes++;
                    left++;
                }
            } else {
                if (currentBoxHeight <= effective_heights[right]) {
                    placedBoxes++;
                    right--;
                }
            }

            boxIndex++;
        }

        return placedBoxes;
    }
}

