public class Solution
{
    public int MinSwaps(int[] data)
    {
        // Step 1: Count the total number of 1s in the array
        int totalOnes = 0;
        for (int i = 0; i < data.Length; i++)
        {
            if (data[i] == 1)
            {
                totalOnes++;
            }
        }

        // If there are no 1s or only one 1, no swaps are needed
        if (totalOnes <= 1)
        {
            return 0;
        }

        // Step 2: Initialize the sliding window
        int minSwaps = int.MaxValue;
        int currentZeros = 0;

        // Count the number of 0s in the initial window
        for (int i = 0; i < totalOnes; i++)
        {
            if (data[i] == 0)
            {
                currentZeros++;
            }
        }

        // Step 3: Slide the window across the array
        for (int i = 0; i <= data.Length - totalOnes; i++)
        {
            // Update the minimum swaps needed
            minSwaps = Math.Min(minSwaps, currentZeros);

            // Slide the window to the right
            if (i + totalOnes < data.Length)
            {
                if (data[i] == 0)
                {
                    currentZeros--;
                }
                if (data[i + totalOnes] == 0)
                {
                    currentZeros++;
                }
            }
        }

        return minSwaps;
    }
}

