using System;
using System.Collections.Generic;

public class Solution {
    public int MinCost(int[][] grid) {
        int m = grid.Length;
        int n = grid[0].Length;

        // Directions: right, left, down, up
        int[][] directions = new int[][] {
            new int[] {0, 1},  // right
            new int[] {0, -1}, // left
            new int[] {1, 0},  // down
            new int[] {-1, 0}  // up
        };

        // Queue for BFS
        Queue<int[]> queue = new Queue<int[]>();
        queue.Enqueue(new int[] {0, 0});

        // Cost array initialized to max value
        int[,] cost = new int[m, n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cost[i, j] = int.MaxValue;
            }
        }
        cost[0, 0] = 0;

        while (queue.Count > 0) {
            int[] current = queue.Dequeue();
            int i = current[0];
            int j = current[1];

            // Check the direction indicated by the current cell
            int dirIndex = grid[i][j] - 1;
            int[] dir = directions[dirIndex];
            int ni = i + dir[0];
            int nj = j + dir[1];

            if (ni >= 0 && ni < m && nj >= 0 && nj < n) {
                if (cost[ni, nj] > cost[i, j]) {
                    cost[ni, nj] = cost[i, j];
                    queue.Enqueue(new int[] {ni, nj});
                }
            }

            // Check all other directions
            for (int d = 0; d < 4; d++) {
                if (d == dirIndex) continue; // Skip the direction already checked

                dir = directions[d];
                ni = i + dir[0];
                nj = j + dir[1];

                if (ni >= 0 && ni < m && nj >= 0 && nj < n) {
                    if (cost[ni, nj] > cost[i, j] + 1) {
                        cost[ni, nj] = cost[i, j] + 1;
                        queue.Enqueue(new int[] {ni, nj});
                    }
                }
            }
        }

        return cost[m - 1, n - 1];
    }
}

