using System;

public class PizzaProblem
{
    public int MaxPizzaSum(int[] slices)
    {
        int n = slices.Length;
        if (n == 1) return slices[0];

        // Helper function to calculate the maximum sum without considering the first or last slice
        int CalculateMaxSum(int[] s, int start, int end)
        {
            int len = end - start + 1;
            if (len == 1) return s[start];
            if (len == 2) return Math.Max(s[start], s[end]);

            int[] dp = new int[len];
            dp[0] = s[start];
            dp[1] = Math.Max(s[start], s[start + 1]);

            for (int i = 2; i < len; i++)
            {
                dp[i] = Math.Max(dp[i - 1], dp[i - 2] + s[start + i]);
            }

            return dp[len - 1];
        }

        // Calculate the maximum sum excluding the first slice and excluding the last slice
        int maxSumExcludingFirst = CalculateMaxSum(slices, 1, n - 1);
        int maxSumExcludingLast = CalculateMaxSum(slices, 0, n - 2);

        // Return the maximum of the two scenarios
        return Math.Max(maxSumExcludingFirst, maxSumExcludingLast);
    }

    public static void Main(string[] args)
    {
        PizzaProblem pp = new PizzaProblem();

        Console.WriteLine(pp.MaxPizzaSum(new int[] { 1, 2, 3, 4, 5, 6 })); // Output: 10
        Console.WriteLine(pp.MaxPizzaSum(new int[] { 8, 9, 8, 6, 1, 1 })); // Output: 16
        Console.WriteLine(pp.MaxPizzaSum(new int[] { 4, 1, 2, 5, 8, 3, 1, 9, 7 })); // Output: 21
        Console.WriteLine(pp.MaxPizzaSum(new int[] { 3, 1, 2 })); // Output: 3
    }
}

