using System;

public class Solution {
    public int NumberWays(int[][] hats) {
        const int MOD = 1_000_000_007;
        int n = hats.Length;

        // Reverse mapping from hats to people
        int[] hatToPeople = new int[41];
        for (int i = 0; i < n; i++) {
            foreach (int hat in hats[i]) {
                hatToPeople[hat] |= (1 << i);
            }
        }

        // DP table
        int[,] dp = new int[1 << n, 41];
        dp[0, 0] = 1;

        // Fill the DP table
        for (int hat = 1; hat <= 40; hat++) {
            for (int mask = 0; mask < (1 << n); mask++) {
                dp[mask, hat] = dp[mask, hat - 1]; // Case 1: Do not use this hat
                int peopleWhoLikeThisHat = hatToPeople[hat];
                for (int person = 0; person < n; person++) {
                    if ((peopleWhoLikeThisHat & (1 << person)) != 0 && (mask & (1 << person)) == 0) {
                        // Case 2: Assign this hat to this person
                        int newMask = mask | (1 << person);
                        dp[newMask, hat] = (dp[newMask, hat] + dp[mask, hat - 1]) % MOD;
                    }
                }
            }
        }

        return dp[(1 << n) - 1, 40];
    }

    public static void Main(string[] args) {
        Solution solution = new Solution();
        int[][] hats1 = new int[][] { new int[] { 3, 4 }, new int[] { 4, 5 }, new int[] { 5 } };
        Console.WriteLine(solution.NumberWays(hats1)); // Output: 1

        int[][] hats2 = new int[][] { new int[] { 3, 5, 1 }, new int[] { 3, 5 } };
        Console.WriteLine(solution.NumberWays(hats2)); // Output: 4

        int[][] hats3 = new int[][] { new int[] { 1, 2, 3, 4 }, new int[] { 1, 2, 3, 4 }, new int[] { 1, 2, 3, 4 }, new int[] { 1, 2, 3, 4 } };
        Console.WriteLine(solution.NumberWays(hats3)); // Output: 24

        int[][] hats4 = new int[][] { new int[] { 1, 2, 3 }, new int[] { 2, 3, 5, 6 }, new int[] { 1, 3, 7, 9 }, new int[] { 1, 8, 9 }, new int[] { 2, 5, 7 } };
        Console.WriteLine(solution.NumberWays(hats4)); // Output: 111
    }
}

