using System;
using System.Collections.Generic;

public class Solution
{
    public int KthSmallest(int[][] mat, int k)
    {
        // Min-heap to store the sums
        var minHeap = new PriorityQueue<int>();

        // Initialize the heap with the first row
        foreach (var num in mat[0])
        {
            minHeap.Push(num);
        }

        // Process each row
        for (int i = 1; i < mat.Length; i++)
        {
            // Temporary heap to store the new sums
            var tempHeap = new PriorityQueue<int>();

            // Get the smallest k elements from the current heap
            for (int j = 0; j < Math.Min(k, minHeap.Count); j++)
            {
                int currentSum = minHeap.Pop();

                // Add each element of the current row to the current sum
                foreach (var num in mat[i])
                {
                    int newSum = currentSum + num;
                    tempHeap.Push(newSum);
                }
            }

            // Replace the minHeap with the tempHeap
            minHeap = tempHeap;
        }

        // The k-th smallest sum is at the top of the heap
        return minHeap.Peek();
    }

    // Priority Queue implementation
    private class PriorityQueue<T> where T : IComparable<T>
    {
        private List<T> items = new List<T>();

        public void Push(T item)
        {
            items.Add(item);
            int childIndex = items.Count - 1;
            while (childIndex > 0)
            {
                int parentIndex = (childIndex - 1) / 2;
                if (items[parentIndex].CompareTo(items[childIndex]) <= 0)
                    break;

                Swap(parentIndex, childIndex);
                childIndex = parentIndex;
            }
        }

        public T Pop()
        {
            T root = items[0];
            items[0] = items[items.Count - 1];
            items.RemoveAt(items.Count - 1);

            int parentIndex = 0;
            while (true)
            {
                int leftChildIndex = 2 * parentIndex + 1;
                int rightChildIndex = 2 * parentIndex + 2;
                int smallerChildIndex = leftChildIndex;

                if (rightChildIndex < items.Count && items[rightChildIndex].CompareTo(items[leftChildIndex]) < 0)
                {
                    smallerChildIndex = rightChildIndex;
                }

                if (smallerChildIndex >= items.Count || items[parentIndex].CompareTo(items[smallerChildIndex]) <= 0)
                    break;

                Swap(parentIndex, smallerChildIndex);
                parentIndex = smallerChildIndex;
            }

            return root;
        }

        public T Peek()
        {
            return items[0];
        }

        public int Count => items.Count;

        private void Swap(int i, int j)
        {
            T temp = items[i];
            items[i] = items[j];
            items[j] = temp;
        }
    }
}

