public class Solution {
    public int MaxNumEdgesToRemove(int n, int[][] edges) {
        // Initialize union-find structures for Alice and Bob
        UnionFind aliceUF = new UnionFind(n);
        UnionFind bobUF = new UnionFind(n);

        int edgesUsed = 0;

        // Process type 3 edges first
        foreach (var edge in edges) {
            if (edge[0] == 3) {
                if (aliceUF.Union(edge[1], edge[2]) || bobUF.Union(edge[1], edge[2])) {
                    edgesUsed++;
                }
            }
        }

        // Process type 1 edges for Alice
        foreach (var edge in edges) {
            if (edge[0] == 1) {
                if (aliceUF.Union(edge[1], edge[2])) {
                    edgesUsed++;
                }
            }
        }

        // Process type 2 edges for Bob
        foreach (var edge in edges) {
            if (edge[0] == 2) {
                if (bobUF.Union(edge[1], edge[2])) {
                    edgesUsed++;
                }
            }
        }

        // Check if both Alice and Bob can traverse the entire graph
        if (aliceUF.GetComponents() != 1 || bobUF.GetComponents() != 1) {
            return -1;
        }

        // Calculate the number of removable edges
        return edges.Length - edgesUsed;
    }

    private class UnionFind {
        private int[] parent;
        private int[] rank;

        public UnionFind(int n) {
            parent = new int[n + 1];
            rank = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
                rank[i] = 1;
            }
        }

        public bool Union(int u, int v) {
            int rootU = Find(u);
            int rootV = Find(v);

            if (rootU == rootV) {
                return false; // Already connected
            }

            if (rank[rootU] > rank[rootV]) {
                parent[rootV] = rootU;
            } else if (rank[rootU] < rank[rootV]) {
                parent[rootU] = rootV;
            } else {
                parent[rootV] = rootU;
                rank[rootU]++;
            }

            return true;
        }

        public int Find(int u) {
            if (parent[u] != u) {
                parent[u] = Find(parent[u]); // Path compression
            }
            return parent[u];
        }

        public int GetComponents() {
            int count = 0;
            for (int i = 1; i < parent.Length; i++) {
                if (parent[i] == i) {
                    count++;
                }
            }
            return count;
        }
    }
}

