using System;

public class Solution
{
    public int MinOperations(int[] target, int[] arr)
    {
        // Step 1: Map values in target to their indices
        int n = target.Length;
        var valueToIndex = new System.Collections.Generic.Dictionary<int, int>();
        for (int i = 0; i < n; i++)
        {
            valueToIndex[target[i]] = i;
        }

        // Step 2: Transform arr into a sequence of indices
        var transformedArr = new System.Collections.Generic.List<int>();
        foreach (var num in arr)
        {
            if (valueToIndex.ContainsKey(num))
            {
                transformedArr.Add(valueToIndex[num]);
            }
        }

        // Step 3: Find the length of the longest increasing subsequence (LIS)
        int lisLength = LengthOfLIS(transformedArr);

        // Step 4: Calculate the minimum number of insertions
        return n - lisLength;
    }

    private int LengthOfLIS(System.Collections.Generic.List<int> nums)
    {
        if (nums.Count == 0) return 0;

        // Use a list to store the smallest tail of all increasing subsequences
        var tails = new System.Collections.Generic.List<int>();

        foreach (var num in nums)
        {
            int left = 0, right = tails.Count;

            // Binary search to find the insertion point
            while (left < right)
            {
                int mid = left + (right - left) / 2;
                if (tails[mid] < num)
                {
                    left = mid + 1;
                }
                else
                {
                    right = mid;
                }
            }

            // If left == tails.Count, it means num is greater than any element in tails
            if (left == tails.Count)
            {
                tails.Add(num);
            }
            else
            {
                tails[left] = num; // Replace the element at the found position
            }
        }

        return tails.Count;
    }

    public static void Main()
    {
        Solution solution = new Solution();

        // Example 1
        int[] target1 = { 5, 1, 3 };
        int[] arr1 = { 9, 4, 2, 3, 4 };
        Console.WriteLine(solution.MinOperations(target1, arr1)); // Output: 2

        // Example 2
        int[] target2 = { 6, 4, 8, 1, 3, 2 };
        int[] arr2 = { 4, 7, 6, 2, 3, 8, 6, 1 };
        Console.WriteLine(solution.MinOperations(target2, arr2)); // Output: 3
    }
}

