solution:
public class Solution {
    public int MinDistance(string word1, string word2) {
        int m = word1.Length;
        int n = word2.Length;

        // Create a 2D array to store the minimum edit distances
        int[,] dp = new int[m + 1, n + 1];

        // Initialize the base cases
        for (int i = 0; i <= m; i++) {
            dp[i, 0] = i; // Deleting all characters from word1
        }
        for (int j = 0; j <= n; j++) {
            dp[0, j] = j; // Inserting all characters into word1
        }

        // Fill the DP table
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (word1[i - 1] == word2[j - 1]) {
                    dp[i, j] = dp[i - 1, j - 1]; // Characters match, no operation needed
                } else {
                    // Minimum of insert, delete, and replace operations
                    dp[i, j] = Math.Min(dp[i - 1, j], Math.Min(dp[i, j - 1], dp[i - 1, j - 1])) + 1;
                }
            }
        }

        // The answer is in the bottom-right corner of the DP table
        return dp[m, n];
    }
}

