        for (int i = 0; i <= m; i++) {
            dp[i, 0] = i; 
        }
        for (int j = 0; j <= n; j++) {
            dp[0, j] = j; 
        }
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (word1[i - 1] == word2[j - 1]) {
                    dp[i, j] = dp[i - 1, j - 1]; 
                } else {
                    dp[i, j] = Math.Min(dp[i - 1, j], Math.Min(dp[i, j - 1], dp[i - 1, j - 1])) + 1;
                }
            }
        }
        return dp[m, n];
    }
}

solution:
using System;

public class Solution {
    public int JobScheduling(int[] startTime, int[] endTime, int[] profit) {
        int n = startTime.Length;

        // Create an array of jobs where each job is represented as (start, end, profit)
        Job[] jobs = new Job[n];
        for (int i = 0; i < n; i++) {
            jobs[i] = new Job(startTime[i], endTime[i], profit[i]);
        }

        // Sort jobs by their end times
        Array.Sort(jobs, (a, b) => a.End.CompareTo(b.End));

        // Initialize DP array
        int[] dp = new int[n];
        dp[0] = jobs[0].Profit;

        // Fill DP array
        for (int i = 1; i < n; i++) {
            // Find the last non-overlapping job using binary search
            int j = BinarySearch(jobs, i);

            // Calculate the maximum profit including the current job
            if (j != -1) {
                dp[i] = Math.Max(dp[i - 1], dp[j] + jobs[i].Profit);
            } else {
                dp[i] = Math.Max(dp[i - 1], jobs[i].Profit);
            }
        }

        // The maximum profit is stored in dp[n-1]
        return dp[n - 1];
    }

    private int BinarySearch(Job[] jobs, int i) {
        int low = 0;
        int high = i - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (jobs[mid].End <= jobs[i].Start) {
                if (jobs[mid + 1].End <= jobs[i].Start) {
                    low = mid + 1;
                } else {
                    return mid;
                }
            } else {
                high = mid - 1;
            }
        }

        return -1;
    }

    private class Job {
        public int Start { get; }
        public int End { get; }
        public int Profit { get; }

        public Job(int start, int end, int profit) {
            Start = start;
            End = end;
            Profit = profit;
        }
    }
}

