using System;
public class Solution {
    public int JobScheduling(int[] startTime, int[] endTime, int[] profit) {
        int n = startTime.Length;
        Job[] jobs = new Job[n];
        for (int i = 0; i < n; i++) {
            jobs[i] = new Job(startTime[i], endTime[i], profit[i]);
        }
        Array.Sort(jobs, (a, b) => a.End.CompareTo(b.End));
        int[] dp = new int[n];
        dp[0] = jobs[0].Profit;
        for (int i = 1; i < n; i++) {
            int j = BinarySearch(jobs, i);
            if (j != -1) {
                dp[i] = Math.Max(dp[i - 1], dp[j] + jobs[i].Profit);
            } else {
                dp[i] = Math.Max(dp[i - 1], jobs[i].Profit);
            }
        }
        return dp[n - 1];
    }
    private int BinarySearch(Job[] jobs, int i) {
        int low = 0;
        int high = i - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (jobs[mid].End <= jobs[i].Start) {
                if (jobs[mid + 1].End <= jobs[i].Start) {
                    low = mid + 1;
                } else {
                    return mid;
                }
            } else {
                high = mid - 1;
            }
        }
        return -1;
    }
    private class Job {
        public int Start { get; }
        public int End { get; }
        public int Profit { get; }
        public Job(int start, int end, int profit) {
            Start = start;
            End = end;
            Profit = profit;
        }
    }
}

