using System;

public class Solution {
    private int[][][] dp;
    private int rows, cols;
    private int[][] grid;

    public int CherryPickup(int[][] grid) {
        this.grid = grid;
        rows = grid.Length;
        cols = grid[0].Length;
        dp = new int[rows][][];

        // Initialize dp array with -1
        for (int i = 0; i < rows; i++) {
            dp[i] = new int[cols][];
            for (int j = 0; j < cols; j++) {
                dp[i][j] = new int[cols];
                for (int k = 0; k < cols; k++) {
                    dp[i][j][k] = -1;
                }
            }
        }

        return MaxCherries(0, 0, cols - 1);
    }

    private int MaxCherries(int row, int col1, int col2) {
        // Base case: if out of bounds, return -infinity
        if (col1 < 0 || col1 >= cols || col2 < 0 || col2 >= cols) {
            return int.MinValue;
        }

        // Base case: if reached the last row, return 0
        if (row == rows) {
            return 0;
        }

        // Return cached result if already computed
        if (dp[row][col1][col2] != -1) {
            return dp[row][col1][col2];
        }

        // Calculate cherries collected at current positions
        int cherries = grid[row][col1];
        if (col1 != col2) {
            cherries += grid[row][col2];
        }

        // Explore all possible moves for both robots
        int maxCherries = 0;
        for (int d1 = -1; d1 <= 1; d1++) {
            for (int d2 = -1; d2 <= 1; d2++) {
                int nextCol1 = col1 + d1;
                int nextCol2 = col2 + d2;
                maxCherries = Math.Max(maxCherries, MaxCherries(row + 1, nextCol1, nextCol2));
            }
        }

        // Store the result in dp array
        dp[row][col1][col2] = cherries + maxCherries;
        return dp[row][col1][col2];
    }
}

